import{_ as r,o,c as t,a5 as a}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"浏览器的缓存机制","description":"title: 浏览器缓存全景图：所有会影响请求的缓存头与机制 date: 2026 03 21 14:18:00 tags: HTTP 浏览器缓存 Cache Control ETag 前端性能categories: 前端 网络 浏览器缓存全景图：所有会影响请求的缓存头与机制 整。","frontmatter":{"title":"浏览器的缓存机制","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","前端知识复习"],"description":"title: 浏览器缓存全景图：所有会影响请求的缓存头与机制 date: 2026 03 21 14:18:00 tags: HTTP 浏览器缓存 Cache Control ETag 前端性能categories: 前端 网络 浏览器缓存全景图：所有会影响请求的缓存头与机制 整。","sidebarWeight":33,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/考点难点/浏览器的缓存机制/浏览器的缓存机制.md"},"headers":[],"relativePath":"posts/前端面试与实战/01-前端知识复习/浏览器的缓存机制/浏览器的缓存机制.md","filePath":"posts/前端面试与实战/01-前端知识复习/浏览器的缓存机制/浏览器的缓存机制.md"}'),l={name:"posts/前端面试与实战/01-前端知识复习/浏览器的缓存机制/浏览器的缓存机制.md"};function s(c,e,n,i,g,h){return o(),t("div",null,[...e[0]||(e[0]=[a('<div><h1 id="浏览器的缓存机制" tabindex="-1">浏览器的缓存机制 <a class="header-anchor" href="#浏览器的缓存机制" aria-label="Permalink to &quot;浏览器的缓存机制&quot;">​</a></h1><blockquote><p>本节目标：理解“浏览器的缓存机制”的核心思路，并能把它用于实际开发或面试表达。 title: 浏览器缓存全景图：所有会影响请求的缓存头与机制 date: 2026-03-21 14:18:00 tags:</p></blockquote><ul><li>HTTP</li><li>浏览器缓存</li><li>Cache-Control</li><li>ETag</li><li>前端性能categories:</li><li>前端</li><li>网络</li></ul><p><strong>浏览器缓存全景图：所有会影响请求的缓存头与机制</strong><strong>整体实现思路</strong> 要把浏览器缓存看明白，最稳的办法不是死记头名，而是先建立一条判断链：</p><ol><li><strong>先看是不是根本没走 HTTP 缓存机制</strong>，例如命中了 bfcache 或被 Service Worker 接管；</li><li><strong>再看 HTTP 缓存有没有可复用条目</strong>；</li><li><strong>再看条目是不是 fresh</strong>；</li><li><strong>如果 stale，是否有验证器（ETag / Last-Modified）可做条件请求</strong>；</li><li><strong>最后再看这次请求自己有没有用 Cache-Control 或 fetch(..., { cache }) 把默认行为改掉。</strong> HTTP 缓存本质上就是“请求头 + 响应头 + 浏览器缓存状态”三方一起决定的。(<a href="https://web.dev/articles/http-cache" target="_blank" rel="noreferrer">web.dev</a>)</li></ol><p><strong>第一步：先分清 4 套“缓存/复用”机制</strong><strong>1）HTTP Cache</strong> 这是最常说的浏览器缓存。浏览器会把“某个请求对应的响应”存起来，后续请求满足条件时直接复用，或者先做条件验证再决定要不要下载正文。Cache-Control、Expires、ETag、Last-Modified、Vary 这些头主要都在管它。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching?utm_source=chatgpt.com" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>2）bfcache</strong> 这是<strong>前进/后退缓存</strong>，不是普通 HTTP 缓存。它保存的是<strong>整页快照</strong>，包括 DOM、JS 堆、页面状态；命中后，浏览器往返前进后退时可以瞬间恢复页面，不需要重新发起那一套网络请求。它和 HTTP cache 完全不是一回事。(<a href="https://developer.mozilla.org/en-US/docs/Glossary/bfcache" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>3）Service Worker + Cache API</strong> Service Worker 像一个运行在浏览器里的代理，可以拦截请求，自己决定是直接走网络、先查 Cache API、还是返回自定义响应。也就是说，它可以<strong>覆盖或绕开</strong>浏览器默认的 HTTP cache 决策。(<a href="https://developer.mozilla.org/en-US/docs/Web/API/Service_Worker_API/Using_Service_Workers" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>4）浏览器主动改写缓存行为</strong> 浏览器普通访问、刷新、强制刷新，以及 fetch(..., { cache }) 的不同 cache mode，都会改变这次请求如何使用 HTTP cache。尤其 Request.cache 的 default、no-store、reload、no-cache、force-cache、only-if-cached，会直接改变“先不先查缓存、是否必须重验证、是否回写缓存”。(<a href="https://developer.mozilla.org/en-US/docs/Web/API/Request/cache" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>第二步：浏览器判断缓存时，真正的顺序是什么</strong><strong>第 1 关：先看是否被别的机制短路</strong> 如果这次是浏览器“后退/前进”恢复页面，优先可能命中 bfcache；如果有 Service Worker 拦截，也可能直接走它自己的逻辑。只有这些都没有接管时，才进入普通 HTTP cache 决策。(<a href="https://developer.mozilla.org/en-US/docs/Glossary/bfcache" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>第 2 关：看有没有“可匹配的缓存条目”</strong> HTTP cache 不是只看 URL。标准匹配至少会受 <strong>方法 + URL + Vary 指定的请求头</strong>影响。若缓存响应带了 Vary: Accept-Encoding, Accept-Language，那下次请求只有这些请求头也匹配时，浏览器才可以直接复用该缓存条目；如果 Vary: *，那这个条目总是匹配失败，不能直接复用。(<a href="https://www.rfc-editor.org/rfc/rfc9111.html" target="_blank" rel="noreferrer">RFC Editor</a>) ==Vary 是一个 HTTP 响应头，意思是“缓存时，要考虑这些因素”。同样的网址，对不同的人，可能返回不同的内容。缓存服务器不能只存一份，要区分对待。== <strong>第 3 关：看这个缓存条目是不是 fresh</strong> freshness 的优先顺序可以这么记：</p><ol><li>对<strong>浏览器私有缓存</strong>，优先看响应里的 Cache-Control: max-age=...。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>)</li><li>Expires 只在没有 max-age 时才有意义；一旦有 max-age，Expires 必须被忽略。(<a href="https://www.rfc-editor.org/rfc/rfc9111.html" target="_blank" rel="noreferrer">RFC Editor</a>)</li><li>Age 表示这个响应在缓存链路里已经“老了多少秒”，浏览器会把它算进响应年龄。(<a href="https://www.rfc-editor.org/rfc/rfc9111.html" target="_blank" rel="noreferrer">RFC Editor</a>)</li><li>如果没有显式过期信息，规范允许浏览器做<strong>启发式缓存</strong>；常见做法会参考 Last-Modified，规范举例里提到“约 10% 的时间差”是典型策略。(<a href="https://www.rfc-editor.org/rfc/rfc9111.html" target="_blank" rel="noreferrer">RFC Editor</a>)</li></ol><p><strong>第 4 关：如果 stale，看能不能做条件请求</strong> ==Stale 在缓存语境下，意思是“过期的/陈旧的”。这份缓存已经“过期”了，但还没扔掉，先凑合用着。== 如果缓存条目过期了，但响应里有验证器，浏览器会发<strong>条件请求</strong>：</p><ul><li>有 ETag 时，通常带 If-None-Match。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching" target="_blank" rel="noreferrer">MDN Web Docs</a>)</li><li>没有 ETag，但有 Last-Modified 时，通常带 If-Modified-Since。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Last-Modified?utm_source=chatgpt.com" target="_blank" rel="noreferrer">MDN Web Docs</a>)</li><li>两者同时存在时，If-None-Match 优先级高于 If-Modified-Since。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching" target="_blank" rel="noreferrer">MDN Web Docs</a>)</li></ul><p>如果服务端判断内容没变，就回 304 Not Modified，浏览器继续用本地副本；如果变了，就回 200 和新内容。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>第 5 关：看这次请求自己有没有“强行改规则”</strong> 即使缓存条目是 fresh，请求端也可能主动改规则：</p><ul><li>fetch(url, { cache: &quot;no-store&quot; })：完全绕过 HTTP cache，也不写回缓存。(<a href="https://developer.mozilla.org/en-US/docs/Web/API/Request/cache" target="_blank" rel="noreferrer">MDN Web Docs</a>)</li><li>fetch(url, { cache: &quot;reload&quot; })：不先查缓存，但网络结果会回写缓存。(<a href="https://developer.mozilla.org/en-US/docs/Web/API/Request/cache" target="_blank" rel="noreferrer">MDN Web Docs</a>)</li><li>fetch(url, { cache: &quot;no-cache&quot; })：即使本地有缓存，也会走条件请求验证。(<a href="https://developer.mozilla.org/en-US/docs/Web/API/Request/cache" target="_blank" rel="noreferrer">MDN Web Docs</a>)</li><li>fetch(url, { cache: &quot;force-cache&quot; })：有缓存就直接用，哪怕 stale。(<a href="https://developer.mozilla.org/en-US/docs/Web/API/Request/cache" target="_blank" rel="noreferrer">MDN Web Docs</a>)</li><li>fetch(url, { cache: &quot;only-if-cached&quot; })：只允许命中 HTTP cache；没有缓存就返回 504，而且只能用于 same-origin。(<a href="https://developer.mozilla.org/en-US/docs/Web/API/Request/cache" target="_blank" rel="noreferrer">MDN Web Docs</a>)</li></ul></div>',1)])])}const p=r(l,[["render",s]]);export{d as __pageData,p as default};
